'use strict';
let SAVE_KEY='lemonade-empire-save-v1';
let saveOK=true,loadingSave=false;
function reward(amount, doubleEligible=true){if(window.cloudPaused)return 0;amount=multiplyAmount(amount,doubleEligible?festivalMultiplier():1);clicks=addAmount(clicks,amount);total=addAmount(total,amount);update();saveGame();return amount;}
function rebirthCost(){return finiteAmount(1e6*Math.pow(10,Math.min(rebirths,90)));}
function rebirthReward(){return total<rebirthCost()?0:Math.min(100,1+Math.floor(Math.log10(total/rebirthCost())));}
function renderFun(){if(!$('legacy-stats'))return;const gain=rebirthReward();$('legacy-stats').textContent=`${fmt(rebirths)} rebirths · ${fmt(zest)} Zest · permanent ×${statsFmt(1+zest*.25)} earnings`;$('rebirth-info').textContent=gain?`Rebirth now for +${gain} Zest. Your next empire starts stronger.`:`Earn ${fmt(rebirthCost())} this run to rebirth (${fmt(total)} earned).`;$('rebirth').disabled=!gain;$('rebirth').textContent=gain?`Rebirth · +${gain} Zest`:'Keep growing';for(const game of Object.keys(ARCADE_GAMES)){const button=$('open-'+game);const unlocked=arcadeUnlocks[game];const price=ARCADE_PRICES[game];button.disabled=window.cloudPaused||(!unlocked&&clicks<price);$(game+'-unlock-label').textContent=unlocked?'Unlocked · Play anytime':`Unlock · ${fmt(price)} bank clicks`;button.setAttribute('aria-label',unlocked?`Play ${ARCADE_GAMES[game].title}`:`Unlock ${ARCADE_GAMES[game].title} for ${price} bank clicks`);}$('arcade-records').textContent=`Arcade records: ${fmt(arcadeBest)} best flappy run · ${fmt(arcadeDodges)} squeezers dodged · ${fmt(cookiesCaught)} cookies caught · ${fmt(lemonsPopped)} lemons popped · ${fmt(ordersServed)} orders served`;$('save-status').textContent=window.cloudSaveMessage|| (saveOK?'Progress saves automatically on this device.':'Your browser blocked saving. Keep this tab open to keep playing.');}
function resetExtras(){window.devPanelUnlocked=false;if(typeof syncDevShortcut==='function')syncDevShortcut();arcadeUnlocks={flappy:false,cookies:false,pop:false,rush:false};rebirths=zest=arcadeDodges=arcadeBest=cookiesCaught=lemonsPopped=ordersServed=deliveries=luckyLemons=festivalUntil=festivalReady=deliveryReady=0;$('golden-lemon').hidden=true;clearFestival();stopArcade();try{localStorage.removeItem(SAVE_KEY);}catch{} }
function performRebirth(){if(window.cloudPaused)return false;const gain=rebirthReward();if(!gain)return false;const awarded=goals.map(g=>g.awarded),unlocked=achievements;rebirths=Math.min(1e6,rebirths+1);zest=Math.min(1e9,zest+gain);clearFestival();reset(true);achievements=unlocked;goals.forEach((g,i)=>g.awarded=awarded[i]);update();saveGame();notify(`Fresh start! +${gain} Zest · ×${statsFmt(1+zest*.25)} permanent earnings`);return true;}
function gameSnapshot(){repairNumbers();return {v:1,devPanelUnlocked:window.devPanelUnlocked===true,arcadeUnlocks:{...arcadeUnlocks},stageId:stages[stage].id,devStageId:Number.isInteger(window.devStageOverride)?stages[window.devStageOverride]?.id:null,clicks,total,taps,purchases,achievements,rebirths,zest,arcadeDodges,arcadeBest,cookiesCaught,lemonsPopped,ordersServed,deliveries,luckyLemons,festivalUntil,festivalReady,deliveryReady,items:Object.fromEntries([...upgrades,...generators,...boosts].map(i=>[i.name,i.owned])),awarded:goals.filter(g=>g.awarded).map(g=>g.name),savedAt:Date.now()};}
function saveGame(){if(loadingSave||window.cloudPaused)return;const snapshot=gameSnapshot();try{localStorage.setItem(SAVE_KEY,JSON.stringify(snapshot));saveOK=true;}catch{saveOK=false;}if(typeof window.accountSaveHook==='function')window.accountSaveHook(snapshot);}
function applySnapshot(s,offline=true){if(!s||s.v!==1||!s.items||typeof s.items!=='object')throw new Error('Invalid save');loadingSave=true;try{stopArcade();clearFestival();window.devPanelUnlocked=s.devPanelUnlocked===true;if(typeof syncDevShortcut==='function')syncDevShortcut();const manualStage=stages.findIndex(world=>world.id===s.devStageId);window.devStageOverride=manualStage>=0?manualStage:null;arcadeUnlocks=Object.fromEntries(Object.keys(ARCADE_GAMES).map(key=>[key,s.arcadeUnlocks?.[key]===true]));clicks=finiteAmount(s.clicks);total=finiteAmount(s.total);taps=finiteAmount(s.taps);purchases=finiteAmount(s.purchases);achievements=s.achievements===true;rebirths=Math.min(1e6,Math.floor(finiteAmount(s.rebirths)));zest=Math.min(1e9,Math.floor(finiteAmount(s.zest)));arcadeDodges=Math.floor(finiteAmount(s.arcadeDodges));arcadeBest=Math.floor(finiteAmount(s.arcadeBest));cookiesCaught=Math.floor(finiteAmount(s.cookiesCaught));lemonsPopped=Math.floor(finiteAmount(s.lemonsPopped));ordersServed=Math.floor(finiteAmount(s.ordersServed));deliveries=Math.floor(finiteAmount(s.deliveries));luckyLemons=Math.floor(finiteAmount(s.luckyLemons));const now=Date.now();festivalUntil=festivalReady=deliveryReady=0;for(const i of [...upgrades,...generators,...boosts])i.owned=finiteAmount(s.items[i.name]);const awarded=new Set(Array.isArray(s.awarded)?s.awarded:[]);goals.forEach(g=>g.awarded=awarded.has(g.name));repairNumbers();const seconds=offline?Math.min(7200,Math.max(0,(now-finiteAmount(s.savedAt))/1000)):0;const earned=multiplyAmount(multiplyAmount(baseRate,autoMult),seconds);clicks=addAmount(clicks,earned);total=addAmount(total,earned);const savedStage=stages.findIndex(x=>x.id===s.stageId);stage=savedStage>=0?savedStage:stages.reduce((n,x,i)=>finiteAmount(s.total)>=x.legacyAt?i:n,0);setScene(stage);update();if(earned)notify(`Welcome back! Your businesses earned ${fmt(earned)} clicks (up to 2 hours).`);}finally{loadingSave=false;}}
function loadGame(){try{const raw=localStorage.getItem(SAVE_KEY);if(raw)applySnapshot(JSON.parse(raw));}catch{notify('Could not read this save. A fresh stand is ready.');}}
$('fun-toggle').addEventListener('click',()=>{renderFun();$('fun-dialog').showModal();});$('fun-close').addEventListener('click',()=>$('fun-dialog').close());
$('rebirth').addEventListener('click',()=>{if(!rebirthReward())return;$('rebirth-confirm-info').textContent=`Gain ${rebirthReward()} permanent Zest. Your bank and shop reset to a new stand. Your achievements and arcade records stay.`;$('rebirth-dialog').showModal();});$('cancel-rebirth').addEventListener('click',()=>$('rebirth-dialog').close());$('confirm-rebirth').addEventListener('click',()=>{performRebirth();$('rebirth-dialog').close();});
function offerGoldenLemon(){if(clicks<=0)return false;return showLemonOffer('golden-lemon');}
setInterval(offerGoldenLemon,45000);
$('golden-lemon').addEventListener('click',()=>{if(!claimLemonOffer('golden-lemon'))return;repairNumbers();const percent=5+Math.floor(Math.random()*21);const amount=multiplyAmount(clicks,percent/100);luckyLemons++;const earned=reward(amount, false);notify(`Golden lemon! +${percent}% of your bank · ${fmt(earned)} bonus clicks`);});
loadGame();renderFun();setInterval(saveGame,2000);window.addEventListener('pagehide',saveGame);document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame();});$('confirm-reset').addEventListener('click',saveGame);
